package com.example.vocab

/** Original teaching definitions/examples; Cambridge Dictionary links document usage checks. */
enum class LexicalRelationType { NEAR_SYNONYM, REGISTER, COLLOCATION, GRAMMAR, USAGE }

data class LexicalSense(val word: String, val partOfSpeech: String, val definition: String,
    val meaningFa: String, val example: String, val index: Int)

data class LexicalRelation(val id: String, val first: LexicalSense, val second: LexicalSense,
    val type: LexicalRelationType, val firstPrompt: String, val secondPrompt: String,
    val firstAnswers: Set<String>, val secondAnswers: Set<String>, val noteFa: String,
    val sources: List<String>, val version: Int = 1,
    val contentLicense: String = "Original LinguaFa teaching text") {
    fun sense(word: String) = if (word.equals(first.word, true)) first else second
    fun partner(word: String) = if (word.equals(first.word, true)) second else first
    fun prompt(word: String) = if (word.equals(first.word, true)) firstPrompt else secondPrompt
    fun answers(word: String) = if (word.equals(first.word, true)) firstAnswers else secondAnswers
}

