    val words: Set<String> = relations.flatMap { listOf(it.first.word, it.second.word) }.toSet()
    fun forWord(word: String, knownWords: Set<String>? = null): LexicalRelation? = relations.firstOrNull {
        (word.equals(it.first.word, true) || word.equals(it.second.word, true)) &&
            (knownWords == null || it.partner(word).word in knownWords)
    }
